import re

def parse_duration(text):
    text = text.strip()
    if not text:
        return None

    # Find all number+unit tokens (e.g., "2h", "30m", "20s")
    tokens = re.findall(r'(\d+)(h|m|s)', text)

    if not tokens:
        # No unit token → must be a plain number of seconds
        if re.fullmatch(r'\d+', text):
            return int(text)
        return None

    # Verify that the whole string is exactly the concatenation of the tokens
    expected = ''.join(f"{num}{unit}" for num, unit in tokens)
    if expected != text:
        return None

    # Validate order: hours, minutes, seconds must appear in non‑decreasing order
    order = {'h': 0, 'm': 1, 's': 2}
    units = [unit for _, unit in tokens]
    for i in range(1, len(units)):
        if order[units[i]] < order[units[i - 1]]:
            return None

    # Each unit must appear at most once
    if len(set(units)) != len(units):
        return None

    # Compute total seconds
    total_seconds = 0
    for num_str, unit in tokens:
        n = int(num_str)
        if unit == 'h':
            total_seconds += n * 3600
        elif unit == 'm':
            total_seconds += n * 60
        elif unit == 's':
            total_seconds += n
        else:
            return None   # should never happen

    return total_seconds
